const rayvn_config = global.get('rayvn_config')
const path = "/logs/" + rayvn_config.log_id + "/entry"

if (!rayvn_config.api_key || !rayvn_config.log_id) {
    node.error('Rayvn not configured. Please submit Rayvn configuration first.');
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key,
    "Content-Type": "application/json",
    "Accept": "application/json"
};

msg.url = global.get("rayvn_url") + path;

return msg;
